import os

def top_lnk(root, n):
    """递归查找 root 下所有 .lnk 文件，按大小降序返回前 n 个 (size, path)。"""
    if n <= 0:
        return []

    found = []
    for dirpath, _dirnames, filenames in os.walk(root):
        for name in filenames:
            if not name.lower().endswith('.lnk'):
                continue
            path = os.path.join(dirpath, name)
            try:
                size = os.path.getsize(path)
            except OSError:
                continue
            found.append((size, path))

    found.sort(key=lambda item: item[0], reverse=True)
    return found[:n]

def dedup(items):
    """去重并保持首次出现顺序，同时支持可哈希与不可哈希元素。"""
    seen_hashable = set()
    seen_unhashable = []
    result = []

    for item in items:
        try:
            hash(item)
        except TypeError:
            if any(item == existing for existing in seen_unhashable):
                continue
            seen_unhashable.append(item)
        else:
            if item in seen_hashable:
                continue
            seen_hashable.add(item)
        result.append(item)

    return result

import time
from functools import wraps

def retry(times=3, delay=0):
    """失败最多重试 times 次（含首次），全部失败时抛出最后一次异常。"""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            last_error = None
            for attempt in range(times):
                try:
                    return func(*args, **kwargs)
                except Exception as error:
                    last_error = error
                    if attempt < times - 1:
                        time.sleep(delay)
            raise last_error

        return wrapper

    return decorator

