import re

_INT_PATTERN = re.compile(r'^[+-]?\d+$')
_FLOAT_PATTERN = re.compile(r'^[+-]?(\d+\.\d*|\.\d+|\d+)([eE][+-]?\d+)?$')

def _convert(value):
    """把纯数字字符串转为 int/float，空值与非数字原样返回。"""
    if not isinstance(value, str):
        return value
    if value == '':
        return ''
    text = value.strip()
    if not text:
        return value
    if _INT_PATTERN.match(text):
        return int(text)
    if _FLOAT_PATTERN.match(text):
        return float(text)
    return value

